function addToCart(cart, item) {
  const line = cart.find((c) => c.item === item)
  if (line) {
    line.qty++
  } else {
    cart.push({ item, qty: 1 })
  }
  return cart
}

function removeById(list, id) {
  const i = list.findIndex((x) => x.id === id)
  if (i === -1) return false
  list.splice(i, 1)
  return true
}

function myFind(list, test) {
  for (const item of list) {
    if (test(item)) return item
  }
  return undefined
}

function pairFor(nums, target) {
  for (let i = 0; i < nums.length; i++) {
    const j = nums.findIndex((n, k) => k > i && nums[i] + n === target)
    if (j !== -1) return [nums[i], nums[j]]
  }
  return null
}

