function countBy(list, key) {
  const groups = Object.groupBy(list, key)
  return Object.fromEntries(Object.entries(groups).map(([k, items]) => [k, items.length]))
}

function monthTotals(sales) {
  const groups = Object.groupBy(sales, (s) => s.month)
  return Object.fromEntries(
    Object.entries(groups).map(([month, list]) => [month, list.reduce((sum, s) => sum + s.amount, 0)]),
  )
}

function ageBands(people) {
  const band = (age) => (age < 18 ? "0-17" : age < 65 ? "18-64" : "65+")
  const groups = Object.groupBy(people, (p) => band(p.age))
  return Object.fromEntries(Object.entries(groups).map(([k, list]) => [k, list.map((p) => p.name)]))
}

function myGroupBy(list, key) {
  const groups = {}
  for (const item of list) {
    const k = key(item)
    ;(groups[k] ??= []).push(item)
  }
  return groups
}

function summary(students) {
  const groups = Object.groupBy(students, (s) => s.cls)
  return Object.entries(groups).map(([cls, list]) => {
    const average = list.reduce((sum, s) => sum + s.score, 0) / list.length
    return `${cls}: average ${Math.round(average)} (${list.length} in class)`
  })
}

function toWatch(movies) {
  return movies.filter((m) => !m.watched)
}

function since(movies, year) {
  return movies
    .filter((m) => m.year >= year)
    .toSorted((a, b) => a.year - b.year)
    .map((m) => m.title)
}

function averageRating(movies) {
  if (movies.length === 0) return 0
  const total = movies.reduce((sum, m) => sum + m.rating, 0)
  return Math.round((total / movies.length) * 10) / 10
}

function best(movies) {
  const top = movies.reduce((top, m) => (top === null || m.rating > top.rating ? m : top), null)
  return top === null ? null : top.title
}

function weekTotal(sales) {
  return sales.reduce((sum, s) => sum + s.qty * s.price, 0)
}

function itemsSold(sales) {
  return [...new Set(sales.map((s) => s.item))].toSorted()
}

function byDay(sales) {
  const groups = Object.groupBy(sales, (s) => s.day)
  return Object.fromEntries(
    Object.entries(groups).map(([day, list]) => [day, list.reduce((sum, s) => sum + s.qty * s.price, 0)]),
  )
}

function qtyByItem(sales) {
  return sales.reduce((acc, s) => {
    acc[s.item] = (acc[s.item] ?? 0) + s.qty
    return acc
  }, {})
}

function bestSeller(sales) {
  const qty = sales.reduce((acc, s) => {
    acc[s.item] = (acc[s.item] ?? 0) + s.qty
    return acc
  }, {})
  return Object.entries(qty).toSorted(([, a], [, b]) => b - a)[0]
}

function report(sales) {
  const money = (n) => `$${n.toFixed(2)}`
  const worth = (s) => s.qty * s.price
  const lines = [`Week: ${money(sales.reduce((sum, s) => sum + worth(s), 0))}`]
  for (const [day, list] of Object.entries(Object.groupBy(sales, (s) => s.day))) {
    lines.push(`${day}: ${money(list.reduce((sum, s) => sum + worth(s), 0))}`)
  }
  const qty = sales.reduce((acc, s) => {
    acc[s.item] = (acc[s.item] ?? 0) + s.qty
    return acc
  }, {})
  const [item, n] = Object.entries(qty).toSorted(([, a], [, b]) => b - a)[0]
  lines.push(`Best seller: ${item} (${n})`)
  return lines
}

function totals(rounds) {
  return rounds.reduce((acc, r) => {
    acc[r.player] = (acc[r.player] ?? 0) + r.score
    return acc
  }, {})
}

function rows(totals) {
  return Object.entries(totals).map(([name, total]) => ({ name, total }))
}

function ranked(rows) {
  return rows.toSorted((a, b) => b.total - a.total || a.name.localeCompare(b.name))
}

function ranks(totals) {
  let last = 0
  return totals.map((t, i) => {
    if (i === 0 || t !== totals[i - 1]) last = i + 1
    return last
  })
}

function board(rounds) {
  const totals = rounds.reduce((acc, r) => {
    acc[r.player] = (acc[r.player] ?? 0) + r.score
    return acc
  }, {})
  const sorted = Object.entries(totals)
    .map(([name, total]) => ({ name, total }))
    .toSorted((a, b) => b.total - a.total || a.name.localeCompare(b.name))
  let rank = 0
  return sorted.map((row, i) => {
    if (i === 0 || row.total !== sorted[i - 1].total) rank = i + 1
    return `${rank}. ${row.name} ${row.total}`
  })
}

function mostImproved(rounds) {
  const groups = Object.groupBy(rounds, (r) => r.player)
  const gains = Object.entries(groups)
    .filter(([, list]) => list.length >= 2)
    .map(([name, list]) => [name, list.at(-1).score - list[0].score])
    .toSorted(([nameA, a], [nameB, b]) => b - a || nameA.localeCompare(nameB))
  return gains.length === 0 ? null : gains[0][0]
}
